static int r8153_mac_clk_speed_down(struct r8152 *tp, bool enable)
{
	int ret;

	/* MAC clock speed down */
	if (enable)
		ret = ocp_word_set_bits(tp, MCU_TYPE_PLA, PLA_MAC_PWR_CTRL2,
					MAC_CLK_SPDWN_EN);
	else
		ret = ocp_word_clr_bits(tp, MCU_TYPE_PLA, PLA_MAC_PWR_CTRL2,
					MAC_CLK_SPDWN_EN);

	return ret;
}
